      "content": "{\n  \"name\": \"dsh-web\",\n  \"version\": \"0.4.16\",\n  \"private\": true,\n  \"description\": \"DeepSeek Harness Web GUI 插件全家桶。皮肤、宠物与社区插件索引已拆分为独立仓库（dsh-skins / dsh-pet / dsh-community-plugins），本仓通过 npm 包内置它们。\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./packages/dsh-web-all/cordis.patch.yml\"\n    }\n  },\n  \"files\": [\n    \"package.json\",\n    \"packages/dsh-web-all/cordis.patch.yml\",\n    \"locale\"\n  ],\n  \"dependencies\": {\n    \"@linxin666/dsh-web-all\": \"^0.4.16\"\n  },\n  \"scripts\": {\n    \"build\": \"node scripts/host-sdk-link.mjs --check && pnpm -r build\",\n    \"deps:install\": \"node scripts/install-deps.mjs\",\n    \"dev:watch\": \"node scripts/dev-watch.mjs\",\n    \"host-sdk:check\": \"node scripts/host-sdk-link.mjs --check\",\n    \"host-sdk:link\": \"node scripts/host-sdk-link.mjs\",\n    \"test\": \"node scripts/host-sdk-link.mjs --check && pnpm -r test\",\n    \"test:standards\": \"node scripts/test-standards.mjs --check\",\n    \"test:standards:write\": \"node scripts/test-standards.mjs --write-baseline\",\n    \"typecheck\": \"node scripts/host-sdk-link.mjs --check && pnpm -r typecheck\",\n    \"aggregate:check\": \"node scripts/aggregate.mjs --check\",\n    \"runtime-deps:check\": \"node scripts/runtime-deps-check.mjs\",\n    \"libs:check\": \"node scripts/lib-artifact-check.mjs\",\n    \"libs:write\": \"node scripts/lib-artifact-check.mjs --write\",\n    \"i18n:check\": \"node scripts/i18n-audit.mjs --check\",\n    \"emoji:check\": \"node scripts/emoji-audit.mjs\",\n    \"lint\": \"oxlint --deny-warnings --format=unix .\",\n    \"test:scripts\": \"node --test scripts/*.test.mjs\",\n    \"test:mount\": \"bash scripts/e2e-mount.sh\",\n    \"coverage:check\": \"node scripts/coverage-gate.mjs\",\n    \"coverage:write\": \"node scripts/coverage-gate.mjs --write-baseline\",\n    \"pr:review\": \"node scripts/pr-review.mjs\",\n    \"docs:check\": \"node scripts/verify-docs.mjs\",\n    \"docs:list\": \"node scripts/verify-docs.mjs --list\",\n    \"docs:write-pair\": \"node scripts/verify-docs.mjs --write\",\n    \"sync-shared\": \"node scripts/sync-shared.mjs\",\n    \"sync-shared:check\": \"node scripts/sync-shared.mjs --check\",\n    \"market:build\": \"node scripts/market-build\",\n    \"market:check\": \"node scripts/market-build --check\",\n    \"market:fetch\": \"node scripts/market-fetch-inputs.mjs\",\n    \"market:verify\": \"node scripts/market-verify-assets.mjs\",\n    \"deploy:market\": \"node scripts/deploy-market\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.1.0\",\n    \"@deepseek-ai/dsh-agent\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-brand\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-sandbox\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-scope\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-session\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-subagent\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-timeout\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-util-crypto\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-util-time\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-util-values\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-web-frontend\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-workspace\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/schemastery\": \"^3.19.0\",\n    \"@playwright/test\": \"^1.62.1\",\n    \"@typescript/native-preview\": \"7.0.0-dev.20260707.2\",\n    \"@vitest/coverage-v8\": \"^4.1.8\",\n    \"es-module-lexer\": \"2.3.2\",\n    \"lightningcss\": \"^1.32.0\",\n    \"oxlint\": \"1.88.0\",\n    \"playwright\": \"^1.62.1\",\n    \"semver\": \"^7.8.5\",\n    \"tsdown\": \"^0.22.2\"\n  },\n  \"license\": \"Apache-2.0\",\n  \"packageManager\": \"pnpm@11.24.0\"\n}\n"
